#!/usr/bin/env bash
set -euo pipefail
ROOT="${1:-build-src/Lios-Hight-RPG}"

mkdir -p "$ROOT/app/src/main/assets"
mkdir -p "$ROOT/app/src/main/java/com/lio/hightrpg"

INDEX_B64=''
JAVA_B64=''
BUILD_B64=''

printf '%s' "$INDEX_B64" | base64 -d | gzip -d > "$ROOT/app/src/main/assets/index.html"
printf '%s' "$JAVA_B64" | base64 -d | gzip -d > "$ROOT/app/src/main/java/com/lio/hightrpg/MainActivity.java"
printf '%s' "$BUILD_B64" | base64 -d | gzip -d > "$ROOT/app/build.gradle"

echo "Applied Lio's Hight RPG v1.1.0 coherence patch"
